"use client";

/**
 * Team channel: a work-chat channel fills itself in. Typing dots come before
 * each message, each message lands with its avatar, name and time, and a
 * reaction lands on the last one.
 *
 * Written by Better Design. Painted from the theme prop; avatars are initials
 * on tints of the primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { Heart } from "@remotion/shapes";
import { AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, shiftHue, springs, unit, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["400", "500", "600", "700"], subsets: ["latin"] });

const FIRST_AT = 18;
/** Typing dots show this long before each message lands. */
const TYPING = 14;
/** Frames the list spends on all messages, shared out between them. */
const LIST_FRAMES = 112;
const START_MINUTE = 9 * 60 + 41;

export interface TeamChannelProps {
  /** The channel name, shown after a hash in the header. */
  channel?: string;
  /** Messages in order, each written as "Name: text". */
  messages?: string[];
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const parse = (line: string) => {
  const at = line.indexOf(":");
  return at < 0 ? { name: "Someone", text: line.trim() } : { name: line.slice(0, at).trim(), text: line.slice(at + 1).trim() };
};

const initials = (name: string) =>
  name
    .split(/\s+/)
    .map((part) => part[0] ?? "")
    .join("")
    .slice(0, 2)
    .toUpperCase();

const hueOf = (name: string) => [...name].reduce((sum, ch) => sum + ch.charCodeAt(0) * 37, 0) % 360;

const clock = (minute: number) => `${Math.floor(minute / 60)}:${String(minute % 60).padStart(2, "0")}`;

function Avatar({ theme, name, size = 64 }: { theme: VideoTheme; name: string; size?: number }) {
  const tint = shiftHue(theme.primary, hueOf(name));
  return (
    <div style={{ width: size, height: size, borderRadius: size * 0.3, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", background: withAlpha(tint, 0.18), color: tint, fontSize: size * 0.38, fontWeight: 700 }}>
      {initials(name)}
    </div>
  );
}

/** A channel that fills in one message at a time, with typing dots and a final reaction. */
export function TeamChannel({
  channel = "launch-week",
  messages = [
    "Maya Lin: The new onboarding flow is ready for review",
    "Sam Ortiz: Looks clean. The empty state reads much better now",
    "Priya Shah: Shipping it to the beta group this afternoon",
    "Maya Lin: Thank you both, great work this week",
  ],
  theme: themeOverride,
  font,
}: TeamChannelProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);
  const per = Math.min(30, LIST_FRAMES / Math.max(1, messages.length));
  const items = messages.map((line, i) => ({ ...parse(line), landAt: FIRST_AT + TYPING + i * per }));
  const reactAt = (items.at(-1)?.landAt ?? FIRST_AT) + 14;

  const windowIn = easings.out(progress(frame, 0, 18));
  const typingFor = items.find((m) => frame >= m.landAt - TYPING && frame < m.landAt);
  const react = spring({ frame: frame - reactAt, fps, config: springs.bouncy });

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div
        style={{
          width: 1240,
          height: 860,
          display: "flex",
          flexDirection: "column",
          borderRadius: theme.radius * 2,
          background: theme.card,
          border: `1px solid ${theme.border}`,
          boxShadow: `0 40px 100px oklch(0 0 0 / 0.1)`,
          overflow: "hidden",
          opacity: windowIn,
          transform: `translateY(${(1 - windowIn) * 30}px)`,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 16, padding: "30px 44px", borderBottom: `1px solid ${theme.border}` }}>
          <span style={{ fontSize: 40, fontWeight: 500, color: theme.mutedForeground }}>#</span>
          <span style={{ fontSize: 38, fontWeight: 700, letterSpacing: "-0.02em", color: theme.cardForeground }}>{channel}</span>
          <div style={{ flex: 1 }} />
          <div style={{ display: "flex" }}>
            {[...new Set(items.map((m) => m.name))].slice(0, 3).map((name, i) => (
              <div key={name} style={{ marginLeft: i ? -12 : 0, borderRadius: 16, border: `3px solid ${theme.card}` }}>
                <Avatar theme={theme} name={name} size={44} />
              </div>
            ))}
          </div>
        </div>
        <div style={{ flex: 1, display: "flex", flexDirection: "column", justifyContent: "flex-end", padding: "0 44px 20px", overflow: "hidden" }}>
          {items.map((m, i) => {
            const t = easings.out(progress(frame, m.landAt, 12));
            const isLast = i === items.length - 1;
            return (
              <div key={i} style={{ display: "grid", gridTemplateRows: `${t}fr`, flexShrink: 0 }}>
                <div style={{ minHeight: 0, overflow: "hidden" }}>
                  <div style={{ display: "flex", gap: 24, padding: "18px 0", opacity: t, transform: `translateY(${(1 - t) * 18}px)` }}>
                    <Avatar theme={theme} name={m.name} />
                    <div style={{ display: "flex", flexDirection: "column", gap: 8, minWidth: 0 }}>
                      <div style={{ display: "flex", alignItems: "baseline", gap: 14 }}>
                        <span style={{ fontSize: 30, fontWeight: 700, color: theme.cardForeground }}>{m.name}</span>
                        <span style={{ fontSize: 24, fontWeight: 500, color: theme.mutedForeground }}>{clock(START_MINUTE + i)}</span>
                      </div>
                      <div style={{ fontSize: 32, fontWeight: 400, lineHeight: 1.35, color: theme.cardForeground }}>{m.text}</div>
                      {isLast && (
                        <div style={{ height: 52, display: "flex", alignItems: "flex-end" }}>
                          <div
                            style={{
                              display: "flex",
                              alignItems: "center",
                              gap: 10,
                              padding: "8px 18px",
                              borderRadius: 999,
                              background: withAlpha(theme.primary, 0.12),
                              border: `2px solid ${withAlpha(theme.primary, 0.45)}`,
                              color: theme.primary,
                              fontSize: 24,
                              fontWeight: 700,
                              opacity: unit(react * 3),
                              transform: `scale(${interpolate(react, [0, 1], [0.4, 1])})`,
                              transformOrigin: "left center",
                            }}
                          >
                            <Heart height={22} fill={theme.primary} />
                            {interpolate(frame, [reactAt + 10, reactAt + 11], [1, 2], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }).toFixed(0)}
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
          <div style={{ height: 44, display: "flex", alignItems: "center", gap: 14, opacity: typingFor ? 1 : 0 }}>
            {[0, 1, 2].map((d) => {
              const lift = Math.max(0, Math.sin((frame / fps) * Math.PI * 4 - d * 0.9));
              return <div key={d} style={{ width: 12, height: 12, borderRadius: 6, background: theme.mutedForeground, opacity: 0.4 + lift * 0.6, transform: `translateY(${-lift * 6}px)` }} />;
            })}
            <span style={{ fontSize: 24, fontWeight: 500, color: theme.mutedForeground }}>{typingFor ? `${typingFor.name} is typing` : ""}</span>
          </div>
        </div>
        <div style={{ margin: "0 44px 36px", padding: "22px 28px", borderRadius: theme.radius * 1.4, border: `2px solid ${theme.border}`, fontSize: 28, color: theme.mutedForeground }}>
          Message #{channel}
        </div>
      </div>
    </AbsoluteFill>
  );
}
